#include <vector>

class Solution {
public:
    std::vector<int> concatWithReverse(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> ans(2 * n);
        for (int i = 0; i < n; ++i) {
            ans[i] = nums[i];
            ans[i + n] = nums[n - 1 - i];
        }
        return ans;
    }
};

class Solution {
    public int[] concatWithReverse(int[] nums) {
        int n = nums.length;
        int[] ans = new int[2 * n];
        for (int i = 0; i < n; i++) {
            ans[i] = nums[i];
            ans[i + n] = nums[n - 1 - i];
        }
        return ans;
    }
}
